fn prime_num(n: u64) -> bool {
    // Since n >= 2, handle the smallest cases quickly.
    if n == 2 || n == 3 {
        return true;
    }
    
    // If n is even and greater than 2, it is not prime.
    if n % 2 == 0 {
        return false;
    }
    
    // Calculate the integer square root of n.
    // We convert n to f64, take sqrt, then floor to u64.
    // Note: This is safe for primality check purposes.
    let limit = (n as f64).sqrt() as u64;
    
    // Check only odd divisors starting from 3 up to limit inclusive.
    let mut divisor = 3;
    while divisor <= limit {
        if n % divisor == 0 {
            return false; // Found a divisor, n is not prime.
        }
        divisor += 2; // Skip even numbers
    }
    
    true // No divisors found, n is prime.
}